import React, { useState } from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';

const AudioContainer = styled.div`
  background: var(--bg-card);
  padding: var(--spacing-6);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-6);
`;

const SectionHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
`;

const SectionTitle = styled.h2`
  font-size: var(--font-size-lg);
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
`;

const StatusBadge = styled.span`
  padding: var(--spacing-2) var(--spacing-3);
  background: ${props => props.isRecording ? 'rgba(239, 68, 68, 0.1)' : 'rgba(107, 114, 128, 0.1)'};
  color: ${props => props.isRecording ? 'var(--danger-color)' : 'var(--text-muted)'};
  border: 1px solid ${props => props.isRecording ? 'rgba(239, 68, 68, 0.2)' : 'rgba(107, 114, 128, 0.2)'};
  border-radius: var(--radius-md);
  font-size: var(--font-size-xs);
  font-weight: 500;
`;

const AudioVisualization = styled.div`
  height: 120px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-4);
  position: relative;
  overflow: hidden;
`;

const WaveformContainer = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  height: 100%;
`;

const WaveBar = styled(motion.div)`
  width: 4px;
  background: ${props => props.isActive ? 'var(--primary-color)' : 'var(--border-color)'};
  border-radius: 2px;
  min-height: 8px;
`;

const AudioControls = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-4);
`;

const ControlButton = styled(motion.button)`
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: ${props => {
    if (props.variant === 'record') return props.isActive ? 'var(--danger-color)' : 'rgba(239, 68, 68, 0.1)';
    if (props.variant === 'primary') return 'var(--primary-color)';
    return 'var(--bg-tertiary)';
  }};
  color: ${props => {
    if (props.variant === 'record') return props.isActive ? 'white' : 'var(--danger-color)';
    if (props.variant === 'primary') return 'white';
    return 'var(--text-secondary)';
  }};
  border: 1px solid ${props => {
    if (props.variant === 'record') return props.isActive ? 'var(--danger-color)' : 'rgba(239, 68, 68, 0.2)';
    if (props.variant === 'primary') return 'var(--primary-color)';
    return 'var(--border-color)';
  }};
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    transform: scale(1.05);
    box-shadow: var(--shadow-lg);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;

const AudioStats = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-4);
`;

const StatItem = styled.div`
  background: var(--bg-primary);
  padding: var(--spacing-4);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
`;

const StatLabel = styled.div`
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  margin-bottom: var(--spacing-1);
`;

const StatValue = styled.div`
  font-size: var(--font-size-lg);
  font-weight: 600;
  color: var(--text-primary);
`;

const TranscriptionPanel = styled.div`
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--spacing-4);
  min-height: 120px;
`;

const TranscriptionHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: between;
  margin-bottom: var(--spacing-3);
`;

const TranscriptionTitle = styled.h3`
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--text-secondary);
  margin: 0;
`;

const TranscriptionText = styled.div`
  color: var(--text-primary);
  line-height: 1.6;
  font-size: var(--font-size-sm);
  max-height: 80px;
  overflow-y: auto;
`;

const AudioSection = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);

  // Generate random waveform bars
  const waveformBars = Array.from({ length: 40 }, (_, i) => ({
    id: i,
    height: Math.random() * 60 + 10
  }));

  const toggleRecording = () => {
    setIsRecording(!isRecording);
  };

  const togglePlayback = () => {
    setIsPlaying(!isPlaying);
  };

  return (
    <AudioContainer>
      <SectionHeader>
        <SectionTitle>Audio Processing</SectionTitle>
        <StatusBadge isRecording={isRecording}>
          {isRecording ? '● Recording' : 'Standby'}
        </StatusBadge>
      </SectionHeader>

      <AudioVisualization>
        <WaveformContainer>
          {waveformBars.map((bar) => (
            <WaveBar
              key={bar.id}
              isActive={isRecording && bar.id % 3 === 0}
              animate={{
                height: isRecording ? [bar.height, bar.height * 0.3, bar.height] : bar.height * 0.3
              }}
              transition={{
                duration: 0.8,
                repeat: isRecording ? Infinity : 0,
                delay: bar.id * 0.02
              }}
            />
          ))}
        </WaveformContainer>
      </AudioVisualization>

      <AudioControls>
        <ControlButton
          variant="record"
          isActive={isRecording}
          onClick={toggleRecording}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {isRecording ? '⏸' : '🎤'}
        </ControlButton>
        
        <ControlButton
          variant="primary"
          onClick={togglePlayback}
          disabled={!isRecording}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {isPlaying ? '⏸' : '▶'}
        </ControlButton>
        
        <ControlButton
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          ⏹
        </ControlButton>
      </AudioControls>

      <AudioStats>
        <StatItem>
          <StatLabel>Duration</StatLabel>
          <StatValue>{isRecording ? '00:45' : '00:00'}</StatValue>
        </StatItem>
        <StatItem>
          <StatLabel>Quality</StatLabel>
          <StatValue>HD</StatValue>
        </StatItem>
        <StatItem>
          <StatLabel>Size</StatLabel>
          <StatValue>2.4 MB</StatValue>
        </StatItem>
      </AudioStats>

      <TranscriptionPanel>
        <TranscriptionHeader>
          <TranscriptionTitle>Live Transcription</TranscriptionTitle>
        </TranscriptionHeader>
        <TranscriptionText>
          {isRecording ? (
            <>
              Welcome to today's meeting. We'll be discussing the quarterly results and planning for the next phase of our project. The key metrics we've achieved include a 25% increase in user engagement...
            </>
          ) : (
            <span style={{ color: 'var(--text-muted)' }}>
              Start recording to see live transcription
            </span>
          )}
        </TranscriptionText>
      </TranscriptionPanel>
    </AudioContainer>
  );
};

export default AudioSection;
